  /// carries the last-known-good numbers.
  bool STALE() const {
    return GetField<uint8_t>(VT_STALE, 0) != 0;
  }
  /// Unix seconds the store numbers were last true; 0 = never read.
  int64_t AS_OF() const {
    return GetField<int64_t>(VT_AS_OF, 0);
  }
  const ::flatbuffers::Vector<::flatbuffers::Offset<NDSIngestEvent>> *EVENTS() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<NDSIngestEvent>> *>(VT_EVENTS);
  }
